function confidenceBadge(score2) {
  if (score2 == null || !Number.isFinite(score2)) return "";
  const cls = score2 >= 0.7 ? "ok" : score2 >= 0.4 ? "warn" : "bad";
  return ` <span class="pill ${cls}" data-confidence="${score2.toFixed(3)}" title="Composed confidence (memory.confidence.v1)">conf ${score2.toFixed(2)}</span>`;
}
