async function initGraph(rootDir, opts = {}) {
  const config = graphConfig(opts);
  const storeUri = resolveStoreUri(rootDir, config);
  await mkdir9(dirname7(storeUri.replace(/^file:\/\//, "")), { recursive: true });
  const configPath2 = await writeConfig(rootDir, config);
  const store = await MemoryStore.open({ uri: storeUri, project: opts.project });
  try {
    const versioning = await applyTierVersioning(store);
    return { config, configPath: configPath2, storeUri, versioning };
  } finally {
    await store.close();
  }
}

